# Dino Frontend - Restore Script
# Generated: 2026-04-24
# Usage: Run from the repo root: /Users/mohsale/Desktop/learning/dino/gen2/frontend
# Each file is base64-encoded. Script writes file only if it does not exist.

$RepoRoot = $PSScriptRoot
if (-not $RepoRoot) { $RepoRoot = Split-Path -Parent $MyInvocation.MyCommand.Path }

function Write-FileIfNotExists {
    param([string]$RelPath, [string]$B64Content)
    $FullPath = Join-Path $RepoRoot $RelPath
    $Dir = Split-Path $FullPath -Parent
    if (-not (Test-Path $Dir)) { New-Item -ItemType Directory -Path $Dir -Force | Out-Null }
    if (-not (Test-Path $FullPath)) {
        $Bytes = [System.Convert]::FromBase64String($B64Content)
        [System.IO.File]::WriteAllBytes($FullPath, $Bytes)
        Write-Host "  [CREATED] $RelPath" -ForegroundColor Green
    } else {
        Write-Host "  [EXISTS]  $RelPath" -ForegroundColor DarkGray
    }
}

function Write-FileAlways {
    param([string]$RelPath, [string]$B64Content)
    $FullPath = Join-Path $RepoRoot $RelPath
    $Dir = Split-Path $FullPath -Parent
    if (-not (Test-Path $Dir)) { New-Item -ItemType Directory -Path $Dir -Force | Out-Null }
    $Bytes = [System.Convert]::FromBase64String($B64Content)
    [System.IO.File]::WriteAllBytes($FullPath, $Bytes)
    Write-Host "  [UPDATED] $RelPath" -ForegroundColor Cyan
}

Write-Host '=== Dino Frontend Restore ===' -ForegroundColor Yellow
